INSERT INTO playbooks (
 role_name,relationship_type,primary_audience,secondary_audience,primary_expertise,core_buyer_problem,positioning_statement,recurring_series,
 weekly_original_posts,weekly_short_posts,weekly_meaningful_comments,weekly_new_connections,monthly_long_form_asset,content_sources,primary_post_formats,
 example_topics,lead_magnet,soft_cta,qualified_buying_signal,lead_handoff_action,cross_team_collaboration,ninety_day_audience_goal,ninety_day_content_goal,
 primary_kpi,secondary_kpi,guardrail,updated_at
) VALUES
('Carrier Pricing and Market Analyst','Contractor','CIOs, procurement teams and technology advisors','Carrier sellers and industry analysts','Carrier pricing patterns, market structures and offer comparison','Buyers lack context for whether quotes and terms are competitive','Helping buyers understand the variables behind telecom pricing without pretending every location is the same','What Drives This Quote?',2,2,20,20,'Quarterly Connectivity Pricing Brief','Approved quote data, public promotions, carrier announcements and anonymized historical experience','Charts, quote breakdowns and analytical posts','Why two nearby addresses receive different prices; NRC versus MRC tradeoffs; term effects','Carrier Quote Comparison Worksheet','I can share the comparison framework.','Buyer shares renewal price, quote discrepancy or multi-carrier evaluation','Route to procurement owner; request address list and requirements through approved channel','Procurement Advisor, Founder and Data Analyst','700 procurement and IT connections','30 posts and one quarterly brief','Pricing-assessment opportunities','Saves, shares and worksheet requests','Use approved, anonymized and current data; never publish confidential carrier rates',CURRENT_TIMESTAMP),
('Carrier Relationship Advisor','Advisor','Enterprise buyers and technology advisors','Carrier account teams and escalation contacts','Carrier capabilities, fit, escalation practices and relationship management','Buyers often select carriers based on logo familiarity rather than location-specific fit and execution','Helping enterprises choose and manage carriers based on actual requirements and local capability','Choosing the Right Carrier for the Job',2,1,15,20,'Carrier Evaluation Scorecard','Carrier experience, public network information and delivery lessons','Text posts, scorecards and balanced comparisons','National versus regional carrier; evaluating support; escalation planning','Carrier Evaluation Scorecard','I can send the scorecard we use.','Buyer is comparing carriers or struggling with incumbent support','Route to enterprise or procurement sales owner','Carrier Analyst, Customer Success Advisor and Project Manager','500 buyer and carrier connections','24 posts and one scorecard','Carrier-comparison consultations','Comments from carrier and buyer audiences','Maintain balanced, factual commentary and disclose material relationships where appropriate',CURRENT_TIMESTAMP),
('Network Engineering Advisor','Advisor','Network architects, infrastructure leaders and IT directors','MSP engineers and solutions architects','WAN architecture, redundancy, bandwidth, routing and access design','Commercial decisions are often made without understanding technical dependencies','Helping IT teams translate business requirements into resilient access and WAN designs','Network Design in Plain English',2,2,20,20,'WAN Requirements Worksheet','Architecture experience, public standards, anonymized designs and troubleshooting lessons','Diagrams, whiteboard videos and technical explainers','Active-active versus failover; BGP basics; circuit diversity; bandwidth planning','WAN Requirements Worksheet','I can share the design-input worksheet.','Network redesign, SD-WAN evaluation, data-center move or resilience concern','Route to solutions engineering with topology and requirements','SD-WAN Advisor, Wireless Advisor and Enterprise Advisor','700 technical connections','30 posts and four diagrams','Technical discovery meetings','Technical saves and shares','Do not provide unsafe implementation instructions or claim to have reviewed a design without adequate facts',CURRENT_TIMESTAMP),
('SD-WAN and SASE Advisor','Advisor','CIOs, network and security leaders','MSPs and transformation consultants','SD-WAN, SASE, underlay design, migration planning and vendor evaluation','Organizations buy overlay platforms without addressing underlay quality, operational ownership or migration sequencing','Helping enterprises align SD-WAN and SASE strategy with the real-world connectivity underneath it','The Underlay Matters',2,1,15,20,'SD-WAN Readiness Assessment','Deployment experience, vendor documentation and architecture lessons','Text posts, migration diagrams and readiness checklists','Underlay diversity; broadband use; managed versus co-managed; migration sequencing','SD-WAN Readiness Checklist','I can send the readiness assessment.','SD-WAN RFP, MPLS replacement, security convergence or multi-site refresh','Route to enterprise architect and sales owner','Network Engineer, Security Advisor and Project Manager','600 network-leader connections','24 posts and one assessment','SD-WAN sourcing opportunities','Assessment requests','Avoid vendor bias and unsupported performance comparisons',CURRENT_TIMESTAMP),
('Wireless and Backup Connectivity Advisor','Advisor','IT directors, retail and field operations leaders','Construction, fleet and remote-site teams','LTE, 5G, fixed wireless, satellite and backup connectivity','Wired circuits may be delayed, unavailable or insufficient as the only access method','Helping organizations use wireless intelligently for backup, temporary and hard-to-reach locations','When Fiber Is Not Ready',2,1,15,20,'Wireless Backup Planning Guide','Wireless deployments, coverage challenges, public coverage data and outage cases','Demos, diagrams and deployment stories','LTE failover; 5G primary access; construction trailers; pop-up sites; satellite backup','Wireless Backup Planning Guide','I can share the wireless use-case matrix.','New location before fiber delivery, rural site, event, temporary facility or resilience requirement','Route with address, application, data use and installation date','Retail Advisor, Manufacturing Advisor and Network Engineer','500 operations and IT connections','24 posts and one guide','Wireless opportunities','Guide requests','Do not guarantee coverage without a site-specific assessment',CURRENT_TIMESTAMP),
('UCaaS and Voice Advisor','Advisor','CIOs, voice managers and IT directors','Contact-center, operations and customer-service leaders','UCaaS, SIP, analog replacement, POTS migration and voice transformation','Organizations underestimate number inventory, analog dependencies, emergency calling and change management','Helping enterprises modernize voice without losing numbers, critical lines or operational control','Voice Migration Mistakes',2,1,15,20,'Voice Migration Inventory Template','Voice migrations, number-porting lessons and operational dependencies','Text posts, inventories and migration stories','POTS replacement; elevator and alarm lines; number porting; UCaaS adoption','Voice Migration Inventory Template','I can send the inventory template.','Phone-system replacement, analog-line audit, office move or contact-center change','Route to voice specialist with seat count, locations and current platform','Project Manager, Compliance Advisor and Enterprise Advisor','500 IT and voice connections','24 posts and one template','Voice discovery calls','Template downloads','Avoid emergency-calling or regulatory guarantees',CURRENT_TIMESTAMP),
('Data Center and Cloud Connectivity Advisor','Advisor','Infrastructure leaders, cloud architects and data-center managers','MSPs and enterprise architects','Colocation, cloud on-ramps, cross-connects, transport and data-center migrations','Data-center and cloud projects depend on access circuits, cross-connect details and coordinated timelines','Helping enterprises connect offices, clouds and data centers without missing the physical dependencies','Cloud Still Needs a Network',2,1,15,20,'Data Center Connectivity Planning Guide','Data-center deployments, cloud connectivity designs and migration lessons','Architecture diagrams and planning checklists','Cloud on-ramps; cross-connect lead times; colo selection; transport diversity','Data Center Connectivity Planning Guide','I can share the dependency checklist.','Colocation move, cloud migration, disaster-recovery project or data-center exit','Route to infrastructure owner with sites, providers and target dates','Network Engineer, Project Manager and Carrier Analyst','500 cloud and infrastructure connections','24 posts and one guide','Data-center connectivity opportunities','Technical stakeholder engagement','Do not expose private network architecture or facility security information',CURRENT_TIMESTAMP),
('Telecom Procurement Advisor','Advisor','CFOs, sourcing leaders and IT procurement','IT and legal teams','RFQs, bid structures, requirements, negotiation and vendor comparison','Telecom sourcing becomes inconsistent when requirements, quotes and contractual terms are not normalized','Helping procurement and IT teams compare telecom offers on more than monthly price','The Telecom Buyer’s Table',2,2,20,25,'Telecom RFQ Template','Negotiation experience, anonymized sourcing events and contract comparisons','Document posts, tables and negotiation lessons','Apples-to-apples quote comparison; term leverage; construction charges; renewal timing','Telecom RFQ and Bid Comparison Template','I can send our bid-comparison structure.','Upcoming RFP, renewal, sourcing initiative or concern about current rates','Route with spend range, service inventory and decision timeline','Carrier Analyst, Contract Advisor and Finance Advisor','800 procurement and finance connections','30 posts and one template','Sourcing projects','Template requests and CFO engagement','Do not disclose protected pricing or represent general advice as legal advice',CURRENT_TIMESTAMP),
('Telecom Contract and Renewal Advisor','Advisor','CFOs, legal teams, procurement and IT executives','Technology advisors and contract managers','Telecom agreements, renewal calendars, notice periods, ETFs and commercial risk','Organizations miss notice windows, accept automatic renewals and fail to connect service changes to contract obligations','Helping organizations understand the operational and financial consequences hidden in telecom agreements','Before You Sign the Renewal',2,1,15,20,'Telecom Contract Review Checklist','Contract experience, common commercial structures and anonymized disputes','Text explainers and deadline checklists','Auto-renewal; termination liability; service-level credits; assignment clauses; renewal calendars','Telecom Contract Review Checklist','I can share the operational checklist we use before legal review.','Renewal notice approaching, merger, relocation, disconnect issue or ETF dispute','Route to procurement owner and recommend legal counsel where appropriate','Procurement Advisor, Finance Advisor and Customer Success Advisor','500 legal, procurement and IT connections','24 posts and one checklist','Contract-review conversations','Checklist downloads','Explicitly state that content is operational perspective, not legal advice',CURRENT_TIMESTAMP),
('Telecom Finance and Cost Optimization Advisor','Advisor','CFOs, controllers and finance leaders','Procurement and IT leaders','Spend visibility, billing, cost allocation, audit and financial comparison','Finance teams struggle to reconcile telecom invoices, commitments, credits and location-level ownership','Helping finance and IT turn telecom spend into something understandable and controllable','Where the Telecom Money Goes',2,1,15,20,'Telecom Spend Baseline Worksheet','Billing analyses, cost models, public financial concepts and anonymized examples','Tables, before-and-after examples and worksheets','Unused services; invoice variance; effective rate; total cost beyond MRC','Telecom Spend Baseline Worksheet','I can send the baseline model.','Expense reduction program, billing dispute, acquisition or inability to inventory spend','Route with invoice count, approximate spend and scope','Procurement Advisor, Contract Advisor and Data Analyst','500 finance and procurement connections','24 posts and one worksheet','Cost-optimization assessments','Worksheet requests','Do not guarantee savings or publish private financial data',CURRENT_TIMESTAMP),
('Implementation and Project Management Advisor','Advisor','IT program managers, store development and infrastructure leaders','Construction teams, carriers and vendors','Telecom provisioning, milestones, dependencies, escalations and multi-site rollout governance','Orders fail because responsibilities, dependencies, construction and acceptance steps are not actively managed','Helping organizations turn signed telecom orders into working services without losing control of the timeline','From Order to Turn-Up',2,2,20,20,'Circuit Implementation Milestone Template','Provisioning experience, delays, escalation lessons and project retrospectives','Timelines, postmortems and practical checklists','FOC dates; site readiness; demarc extensions; testing; construction; acceptance','Circuit Implementation Milestone Tracker','I can share the milestone tracker.','Buyer mentions delayed installs, openings, migrations or lack of carrier status','Route to implementation sales owner with affected orders and critical dates','Retail Advisor, Construction Advisor and Customer Success Advisor','600 program-management and IT connections','30 posts and one tracker','Implementation-managed opportunities','Tracker downloads','Never expose live customer order details or blame named individuals',CURRENT_TIMESTAMP)
